function OverSeaManageSettingLeftFoodCell:CalculationExp(index)
    if self.index == index then
        local exp = 0
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local recipeDojo = maidCoffeePlayerComponent:GetRecipeDoJoById(self.data.refId)
        if recipeDojo then
            local num = isNull(self.data.curInputNum) and 1 or self.data.curInputNum
            local makeGetExp = tonumber(self.data.experienceAdd[1]) * num + recipeDojo.exp
            exp = makeGetExp
        end
        self:RefreshExp(exp)
    end
end

