function OverSeaManageSettingLeftFoodCell:RefreshPrice(isMenuDouble,rate)
    ---@type MaidCoffeePlayerComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local recipeInfo =component:GetRecipeDoJoById(self.data.refId)
    KTool.SetActive(self.SellingPriceNode.gameObject,not isNull(recipeInfo))
    if recipeInfo then
        local price = self.data:GetPrice(recipeInfo.rating)
        if price then
            if isMenuDouble then
                price = price * rate
            end
            CfUtils.FillText(self.SalePrice,math.floor(price))
            local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            CfUtils.FillImage(self.SaleIcon,goodsVo.photoPath)
        end
        local isInActivity = self:IsInActivity()
        KTool.SetActive(self.UP.gameObject,isInActivity)
    end
end

function OverSeaManageSettingLeftFoodCell:IsInActivity()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local homeDojo = component:GetMaidCoffeeHomeDoJo()
    local isInActivity = homeDojo:IsActivity()
    return isInActivity
end

function OverSeaManageSettingLeftFoodCell:RefreshCanMake()
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local recipeInfo =component:GetRecipeDoJoById(self.data.refId)
    if recipeInfo then
        local canMake = self:IsCanMake()
        KTool.SetActive(self.CanMake.gameObject,canMake)
    else
        KTool.SetActive(self.CanMake.gameObject,false)
    end
end

function OverSeaManageSettingLeftFoodCell:RefreshCanGet()
    local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.refId)
    if not isNull(foodVo) then
        if isSet(foodVo, "jumpAway") and table.count(foodVo.jumpAway) > 0 then
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
            local canJump = goodsConfMgr:CheckIsCanJump(row,false)
            if canJump then
                if isSet(foodVo,"jumpParameter") then
                    local type = GoodsUtils.GetIdType(foodVo.jumpParameter[1], Constants.IDArea.Quests)
                    if type == Constants.IDType.QuestRegion then
                        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                        local isUnLock =  ActionUtils.IsUnlockRegionQuest(foodVo.jumpParameter[1])
                        local mapVo = CfUtils.GetCfVo(AutoIds.IdSetting3022, "RegionQuestVo", foodVo.jumpParameter[1])
                        local teamPower = GameUtils.GetHistoryTeamPower()
                        local IsCanGet = isUnLock and teamPower >= mapVo.proposalLevel
                        if IsCanGet then
                            KTool.SetActive(self.AvailableRemind.gameObject,true)
                        else
                            KTool.SetActive(self.AvailableRemind.gameObject,false)
                        end
                    else
                        local canJump = goodsConfMgr:CheckIsCanJump(row,false)
                        if canJump then
                            KTool.SetActive(self.AvailableRemind.gameObject,true)
                        else
                            KTool.SetActive(self.AvailableRemind.gameObject,false)
                        end
                    end
                else
                    local canJump = goodsConfMgr:CheckIsCanJump(row,false)
                    if canJump then
                        KTool.SetActive(self.AvailableRemind.gameObject,true)
                    else
                        KTool.SetActive(self.AvailableRemind.gameObject,false)
                    end
                end
            else
                KTool.SetActive(self.AvailableRemind.gameObject,false)
            end
        else
            printError("id %s  不能前往跳转 没有配置openType",foodVo.id)
        end
    end
end

function OverSeaManageSettingLeftFoodCell:IsCanMake()
    local count = #self.data.foodStuff
    local index = 0
    for i = 1, count do
        local haveNum = GoodsUtils.GetThingNo(self.data.foodStuff[i])
        local needNum = tonumber(self.data.foodStuffNum[i])
        if haveNum >= needNum then
            index = index + 1
        end
    end
    return index == count and true or false
end

function OverSeaManageSettingLeftFoodCell:RefreshExp(_exp)
    if not isNull(_exp) then
        self.data.cacheExp = _exp
    end
    ---@type MaidCoffeePlayerComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local recipeDojo =component:GetRecipeDoJoById(self.data.refId)
    if recipeDojo then
        KTool.SetActive(self.ProgressGroup.gameObject,true)
        local recipeInfo = component:GetRecipeInfoByExp(self.data.refId,recipeDojo.exp)
        if recipeInfo then
            KTool.SetActive(self.TxtMax.gameObject,recipeInfo.isToMax)
            KTool.SetActive(self.MaxNode.gameObject,recipeInfo.isToMax)
            KTool.SetActive(self.MaxNode.gameObject,recipeInfo.isToMax)
            KTool.SetActive(self.SliderNode.gameObject,not recipeInfo.isToMax)
            KTool.SetActive(self.ProgressNum.gameObject,not recipeInfo.isToMax)
            KTool.SetActive(self.PreSlider.gameObject,false)
            self.Rate.Status = recipeInfo.rating
            KTool.SetActive(self.CurSlider.gameObject,true)
            KTool.SetActive(self.TxtLevelUp.gameObject,false)
            if recipeInfo.isToMax then
                self.CurSlider.value = 1
                return
            end
            local isPreShow = (not isNull(_exp))
            local progress = recipeInfo.leaveExp/recipeInfo.needExp
            local str = string.format("%s/%s",recipeInfo.leaveExp,recipeInfo.needExp)
            CfUtils.FillText(self.ProgressNum,str)
            self.CurSlider.value = recipeInfo.leaveExp/recipeInfo.needExp
            if isPreShow then
                KTool.SetActive(self.PreSlider.gameObject,true)
                local preRecipeInfo = component:GetRecipeInfoByExp(self.data.refId,self.data.cacheExp)

                KTool.SetActive(self.TxtMax.gameObject,preRecipeInfo.isToMax)
                KTool.SetActive(self.ProgressNum.gameObject,not preRecipeInfo.isToMax)
                --self.Rate.Status = preRecipeInfo.rating
                KTool.SetActive(self.TxtLevelUp.gameObject,preRecipeInfo.rating > recipeDojo.rating)
                KTool.SetActive(self.CurSlider.gameObject,preRecipeInfo.rating <= recipeDojo.rating)

                KTool.SetActive(self.PreSlider.gameObject,true)
                local preProgress = preRecipeInfo.leaveExp/preRecipeInfo.needExp
                local addProgress = preProgress - progress
                if preRecipeInfo.isToMax then
                    self.PreSlider.value = 1
                    --CfUtils.FillText(self.ProgressNum,"100%")
                else
                    if preRecipeInfo.rating > recipeDojo.rating then
                        addProgress = 1 - progress
                        self.PreSlider.value = 1
                    else
                        self.PreSlider.value = preRecipeInfo.leaveExp/preRecipeInfo.needExp
                    end
                    --local str = string.format("<color=#6B5645>%s</color><color=#FF8400>+%s</color>",table.concat({string.format("%.2f",progress * 100),"%"}),table.concat({string.format("%0.2f",addProgress * 100),"%"}))
                    local str = string.format("<color=#FF6E02>%s</color>/%s",preRecipeInfo.leaveExp,preRecipeInfo.needExp)
                    CfUtils.FillText(self.ProgressNum,str)
                end
            end
        end
    end
end

function OverSeaManageSettingLeftFoodCell:OnBtnClick()
