    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local serverInfo =component:GetRecipeDoJoById(self.data.refId)
    if not isNull(serverInfo) then
        self:OnSelect()
    else
        if not self.isPopTip then
            local Vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.refId)
            GameUtils.Toast(localize("获取_name_后解锁", { _name_ = Vo.name}))
        else
            self:OnSelect()
        end
    end
end

